"""Absolute maximum-size request: 128 traces, 6144 rows, 32 fields, K=8,
4096/128/1024 contexts, 16 training sources, 20 heavy quantified atoms."""
import json, random, sys, subprocess, time
from collections import Counter

def build(seed=0, always_true=False):
    rnd = random.Random(seed)
    schema = []
    for i in range(32):
        t = ['TIME', 'SIZE', 'COUNT', 'ID', 'FLAG'][i % 5]
        name = 'f%02d' % i
        if t == 'ID':
            schema.append({'name': name, 'type': 'ID', 'values': ['v%d' % j for j in range(6)]})
        elif t == 'FLAG':
            schema.append({'name': name, 'type': 'FLAG'})
        else:
            schema.append({'name': name, 'type': t, 'min': -20, 'max': 20})
    numeric = [f for f in schema if f['type'] in ('TIME', 'SIZE', 'COUNT')]
    K = 8

    def heavy_atom(idx):
        ftype = numeric[idx % len(numeric)]['type']
        same = [f for f in numeric if f['type'] == ftype]
        fname = same[idx % len(same)]['name']
        f2 = same[(idx + 1) % len(same)]['name']
        f3 = same[(idx + 2) % len(same)]['name']
        if always_true:
            left = {'add': [{'field': fname, 'at': '$'},
                            {'const': 1000, 'type': ftype}]}
            right = {'const': 0, 'type': ftype}
        else:
            left = {'add': [
                {'scale': (idx % 7) + 1, 'term': {'field': fname, 'at': '$'}},
                {'add': [{'field': f2, 'at': idx % K},
                         {'aggregate': 'sum', 'field': f3, 'from': 0, 'to': 2}]}]}
            right = {'add': [
                {'scale': -((idx % 5) + 1), 'term': {'field': fname, 'at': '$'}},
                {'const': (idx % 17) - 8, 'type': ftype}]}
        return {'quantifier': 'all', 'from': 0, 'to': K - 1,
                'predicate': {'cmp': 'ge', 'left': left, 'right': right}}

    atoms = [heavy_atom(i) for i in range(20)]

    def rand_row():
        vals = []
        for f in schema:
            if f['type'] == 'ID': vals.append(rnd.choice(f['values']))
            elif f['type'] == 'FLAG': vals.append(rnd.random() < 0.5)
            else: vals.append(rnd.randint(-20, 20))
        return vals

    def trace(tid, src, n):
        return {'id': tid, 'source': src,
                'rows': [{'t': i * 3, 'values': rand_row()} for i in range(n)]}

    train = [trace('T%02d' % i, 's%d' % (i % 16), 263) for i in range(16)]
    probes = [trace('P%02d' % i, 's0', 15) for i in range(16)]   # 16*(15-7)=128 ctx
    queries = [trace('Q%02d' % i, 's0', 55) for i in range(19)]  # 19*48=912
    queries.append(trace('Q19', 's0', 47))                       # +40 = 952
    return {'version': 1, 'schema': schema, 'window': K, 'atoms': atoms,
            'policy': {'max_width': 4, 'min_support': 1, 'min_witness': 1},
            'train': train, 'probes': probes, 'queries': queries}

if __name__ == '__main__':
    req = build(always_true=('at' in sys.argv))
    data = json.dumps(req).encode()
    print('rows=%d traces=%d bytes=%d' % (
        sum(len(t['rows']) for t in req['train'] + req['probes'] + req['queries']),
        len(req['train']) + len(req['probes']) + len(req['queries']), len(data)), file=sys.stderr)
    t0 = time.time()
    p = subprocess.run([sys.executable, '/app/submission/main.py'], input=data, capture_output=True)
    el = time.time() - t0
    print('rc=%d wall=%.2fs %s' % (p.returncode, el, p.stderr.decode()[-400:]))
    r = json.loads(p.stdout.decode())
    if 'error' in r: print('ERROR', r)
    else:
        print('classes=%d members=%d queries=%d' % (
            len(r['classes']), sum(c['members'] for c in r['classes']), len(r['queries'])))
        print('statuses', Counter(q['status'] for q in r['queries']))
